import{_ as a,o as t,c as r,a5 as l}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"变彩（游彩）","description":"","frontmatter":{"title":"变彩（游彩）","phenomenon":"play-of-color"},"headers":[],"relativePath":"zh/classification/optical-phenomena/play-of-color.md","filePath":"zh/classification/optical-phenomena/play-of-color.md","lastUpdated":1790876393000}'),o={name:"zh/classification/optical-phenomena/play-of-color.md"};function s(i,e,n,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="变彩-游彩" tabindex="-1">变彩（游彩） <a class="header-anchor" href="#变彩-游彩" aria-label="Permalink to &quot;变彩（游彩）&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>变彩是欧泊最具代表性的视觉现象。白光进入欧泊内部由规则排列的二氧化硅小球形成的微结构时， 不同波长的光会发生衍射与干涉；当观察角度改变，呈现跳动、游移的光谱色斑。变彩的强弱、颜色范围 与分布受微结构有序程度、体色、切磨方式和观察光线共同影响。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>微结构衍射与干涉：欧泊中规则排列的二氧化硅小球及其间隙形成周期性结构。白光进入后，不同波长 沿不同方向增强或减弱，因此观察方向变化时会连续看到不同的色彩组合。这里的“游彩”描述的是视觉 表现，不等同于普通的体色或单一光源下的闪光。</p><h2 id="示例宝石" tabindex="-1">示例宝石 <a class="header-anchor" href="#示例宝石" aria-label="Permalink to &quot;示例宝石&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>微结构</th><th>色彩表现</th></tr></thead><tbody><tr><td>Precious Opal / 贵欧泊</td><td>ordered silica-sphere domains</td><td>angular spectral flashes</td></tr><tr><td>Black Opal / 黑欧泊</td><td>dark body tone + silica-sphere domains</td><td>red, green, blue</td></tr><tr><td>White Opal / 白欧泊</td><td>silica-sphere domains</td><td>green, blue, orange</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/articles/gems-gemology-summary-guide-to-phenomenal-gems" target="_blank" rel="noreferrer">GIA：现象宝石指南</a><span>光学现象的观察方式与宝石学语境</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/optical-effects-phenomenal-cabochons" target="_blank" rel="noreferrer">GIA：现象弧面宝石的光学效应</a><span>弧面切割、光源、角度与光学表现</span><small>打开来源 ↗</small></li></ul></aside><p><em>详见<a href="./intro.html">光学现象总览</a>。</em></p>',9)])])}const f=a(o,[["render",s]]);export{m as __pageData,f as default};
